<?php
namespace App\Policies; use App\Domain\Tenancy\TenantContext; use App\Models\{SettlementBatch,User}; final class SettlementBatchPolicy{public function viewAny(User$u):bool{return$u->memberships()->where('status','ACTIVE')->exists();}public function view(User$u,SettlementBatch$m):bool{return$m->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,SettlementBatch$m):bool{return false;}public function delete(User$u,SettlementBatch$m):bool{return false;}}
